import React from 'react';
import { Link } from 'react-router-dom';

const CATEGORIES = [
  { name: 'All Products', icon: '✨', path: '/products' },
  { name: 'Grocery', icon: '🛒', path: '/category/Grocery' },
  { name: 'Bakery', icon: '🍰', path: '/category/Bakery' },
  { name: 'Plants', icon: '🌿', path: '/category/Plants' },
  { name: 'Apparel', icon: '👕', path: '/category/Apparel' },
  { name: 'Shoes', icon: '👟', path: '/category/Shoes' },
  { name: 'Stationery', icon: '✏️', path: '/category/Stationery' },
  { name: 'Sports', icon: '⚽', path: '/category/Sports' },
  { name: 'Furniture', icon: '🪑', path: '/category/Furniture' },
  { name: 'Books', icon: '📚', path: '/category/Books' },
];

export const CategoryPills = () => {
  return (
    <div className="mobile-category-bar" aria-label="Explore Categories">
      <div className="category-pills-scroll">
        {CATEGORIES.map((cat) => (
          <Link
            key={cat.name}
            to={cat.path}
            className="mobile-category-chip"
          >
            <span className="chip-icon">{cat.icon}</span>
            <span className="chip-name">{cat.name}</span>
          </Link>
        ))}
      </div>
    </div>
  );
};

export default CategoryPills;
